<script setup lang="ts">
import { computed, onScopeDispose, shallowRef, watch } from 'vue'
import { ElButton } from 'element-plus'
import RuleEditor from './RuleEditor.vue'
import RuleImportDialog from './RuleImportDialog.vue'
import RuleTextEditor from './RuleTextEditor.vue'
import RuleProviderEditor from './RuleProviderEditor.vue'
import DiagnosticsList from '../../components/DiagnosticsList.vue'
import { useRuleOrder } from './useRuleOrder'
import { downloadText, ruleText, targetLabel } from './ruleText'
import { errorMessage, request } from '../../api/client'
import type { NodeSummary, ProfileDocument, ProviderDefinition, RuleDefinition, ValidationReport } from '../../types/domain'
const props = withDefaults(defineProps<{profileId:string;version:string;document:ProfileDocument;nodes:readonly NodeSummary[];diagnostics:ValidationReport;mode?:'rules'|'providers'}>(),{mode:'rules'})
const emit = defineEmits<{ updateRules:[rules:RuleDefinition[]];updateProviders:[providers:ProviderDefinition[]] }>()
const keyword=shallowRef(''),page=shallowRef(1),editing=shallowRef<RuleDefinition|null>(null),editorOpen=shallowRef(false),importOpen=shallowRef(false),providerOpen=shallowRef(false),editingProvider=shallowRef<ProviderDefinition|null>(null)
const positions=shallowRef<Record<string,number>>({}),error=shallowRef(''),busy=shallowRef(false),checked=shallowRef<ValidationReport|null>(null)
const textOpen=shallowRef(false)
const order=useRuleOrder(()=>props.document.rules),rows=computed(()=>props.document.rules.map((rule,index)=>({rule,index,text:ruleText(rule,props.document,props.nodes),target:targetLabel(rule.target,props.document,props.nodes)})))
const filtered=computed(()=>rows.value.filter(row=>`${row.text} ${row.target}`.toLocaleLowerCase().includes(keyword.value.toLocaleLowerCase())))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/50))),visible=computed(()=>filtered.value.slice((page.value-1)*50,page.value*50))
const report=computed(()=>checked.value??props.diagnostics)
watch(keyword,()=>{page.value=1});watch(pages,count=>{if(page.value>count)page.value=count});watch(()=>props.document,()=>{checked.value=null})
const lifetime=new AbortController();onScopeDispose(()=>lifetime.abort())
function edit(rule:RuleDefinition|null){editing.value=rule;editorOpen.value=true}
function applyRule(rule:RuleDefinition){emit('updateRules',props.document.rules.some(value=>value.id===rule.id)?props.document.rules.map(value=>value.id===rule.id?rule:value):order.insertBeforeMatch(rule));editorOpen.value=false}
function move(id:string,position:number){emit('updateRules',order.moveById(id,position));positions.value={}}
function remove(id:string){emit('updateRules',props.document.rules.filter(rule=>rule.id!==id||rule.expression.type==='MATCH'))}
function editProvider(provider:ProviderDefinition|null){editingProvider.value=provider;providerOpen.value=true}
function applyProvider(provider:ProviderDefinition){emit('updateProviders',props.document.providers.some(item=>item.id===provider.id)?props.document.providers.map(item=>item.id===provider.id?provider:item):[...props.document.providers,provider]);providerOpen.value=false}
const usedProviders=computed(()=>new Set(props.document.rules.flatMap(rule=>rule.expression.providerId?[rule.expression.providerId]:[])))
function removeProvider(id:string){if(!usedProviders.value.has(id))emit('updateProviders',props.document.providers.filter(provider=>provider.id!==id))}
async function validate(){const original=props.document;busy.value=true;error.value='';try{const result=await request<ValidationReport>(`/profiles/${props.profileId}/draft/validate`,{method:'POST',body:original,signal:lifetime.signal});if(props.document===original)checked.value=result}catch(cause){error.value=errorMessage(cause)}finally{busy.value=false}}
function exportRules(){downloadText('rules.txt',rows.value.map(row=>row.text).join('\n')+'\n')}
</script>
<template><section class="panel rules-panel"><header class="panel-header"><div><h2>{{ mode==='rules'?'分流规则':'远程规则集' }}</h2><p class="muted">{{ mode==='rules'?'从上到下匹配；移动位置使用完整列表中的序号。':'仅属于当前方案，由客户端按周期下载。' }}</p></div><div class="actions" v-if="mode==='rules'"><ElButton @click="textOpen=true">文本编辑</ElButton><ElButton @click="importOpen=true">批量导入</ElButton><ElButton @click="exportRules">导出规则文本</ElButton><ElButton type="primary" @click="edit(null)">添加规则</ElButton></div><ElButton v-else type="primary" @click="editProvider(null)">添加规则集</ElButton></header><div class="panel-body"><template v-if="mode==='rules'"><div class="toolbar"><input v-model="keyword" class="rule-search" placeholder="筛选条件或目标…" aria-label="筛选规则"><span class="muted">匹配 {{ filtered.length }} / 共 {{ document.rules.length }} 条</span></div><div class="rules-scroll scroll-area"><table><thead><tr><th>顺序</th><th>类型 / 匹配内容</th><th>目标</th><th>调整顺序</th><th>操作</th></tr></thead><tbody><tr v-for="row in visible" :key="row.rule.id" :data-rule-id="row.rule.id"><td>{{ row.index+1 }}</td><td class="rule-expression"><span class="tag" :class="{success:row.rule.expression.type==='MATCH'}">{{ row.rule.expression.type }}</span><p>{{ row.rule.expression.providerId ? document.providers.find(provider=>provider.id===row.rule.expression.providerId)?.name??'待处理规则集' : row.rule.expression.value }}</p><p v-if="row.rule.issues.some(issue=>issue.severity==='ERROR')" class="danger">待处理</p><details v-if="row.rule.rawText"><summary>原文</summary><pre>{{ row.rule.rawText }}</pre></details><p v-for="(issue,i) in row.rule.issues" :key="i" class="rule-reason" :class="issue.severity==='ERROR'?'danger':'muted'">{{ issue.message }}</p></td><td class="rule-target">{{ row.target }}</td><td><div class="rule-order"><button class="icon-button" :aria-label="`上移规则 ${row.rule.id}`" :disabled="row.index===0||row.rule.expression.type==='MATCH'" @click="move(row.rule.id,row.index)">↑</button><button class="icon-button" :aria-label="`下移规则 ${row.rule.id}`" :disabled="row.index>=document.rules.length-2||row.rule.expression.type==='MATCH'" @click="move(row.rule.id,row.index+2)">↓</button><input :value="positions[row.rule.id]??row.index+1" type="number" min="1" :max="Math.max(1,document.rules.length-1)" :aria-label="`规则 ${row.rule.id} 的绝对位置`" :disabled="row.rule.expression.type==='MATCH'" @input="event=>positions={...positions,[row.rule.id]:Number((event.target as HTMLInputElement).value)}"><button class="text-button" :aria-label="`移动规则 ${row.rule.id}`" :disabled="row.rule.expression.type==='MATCH'" @click="move(row.rule.id,positions[row.rule.id]??row.index+1)">移动</button></div></td><td><div class="actions"><button class="text-button" :aria-label="`编辑规则 ${row.rule.id}`" @click="edit(row.rule)">编辑</button><button class="text-button danger" :disabled="row.rule.expression.type==='MATCH'" :aria-label="`删除规则 ${row.rule.id}`" @click="remove(row.rule.id)">删除</button></div></td></tr></tbody></table></div><div class="toolbar rules-pagination"><span class="muted">第 {{ page }} / {{ pages }} 页 · 每页 50 条</span><div class="actions"><ElButton :disabled="page===1" @click="page--">上一页</ElButton><ElButton :disabled="page===pages" @click="page++">下一页</ElButton></div></div><p class="muted rule-note">导出文本使用节点原名称；同名节点再次导入时需确认目标。完整配置可在发布页面下载。</p></template><template v-else><article v-for="provider in document.providers" :key="provider.id" class="provider-row"><div><h3>{{ provider.name }}</h3><p class="muted">{{ provider.behavior }} / {{ provider.format }} · {{ provider.interval }} 秒<span v-if="usedProviders.has(provider.id)"> · 已被规则引用</span></p></div><div class="actions"><ElButton @click="editProvider(provider)">编辑</ElButton><button class="text-button danger" :disabled="usedProviders.has(provider.id)" :aria-label="`删除规则集 ${provider.name}`" @click="removeProvider(provider.id)">删除</button></div></article><div v-if="!document.providers.length" class="empty-state"><h2>还没有远程规则集</h2><p>添加后，可在分流规则中选择 RULE-SET 和目标代理组。</p></div></template><p v-if="error" class="error" role="alert">{{ error }}</p><DiagnosticsList :items="[...report.errors,...report.warnings].filter(issue=>issue.path.startsWith(mode==='rules'?'rules':'providers'))" /><div class="toolbar rule-validation"><p v-if="checked && !checked.errors.length" class="muted">结构校验通过，发布时还会进行内核校验。</p><ElButton :loading="busy" @click="validate">校验当前{{ mode==='rules'?'规则':'规则集' }}</ElButton></div></div></section><RuleEditor v-if="editorOpen" :rule="editing" :document="document" :nodes="nodes" @apply="applyRule" @close="editorOpen=false" /><RuleTextEditor v-if="textOpen" :profile-id="profileId" :version="version" :document="document" @apply="rules=>{emit('updateRules',rules);textOpen=false}" @close="textOpen=false" /><RuleImportDialog v-if="importOpen" :profile-id="profileId" :version="version" :document="document" @apply="result=>{emit('updateRules',result.rules);importOpen=false}" @close="importOpen=false" /><RuleProviderEditor v-if="providerOpen" :provider="editingProvider" :providers="document.providers" @apply="applyProvider" @close="providerOpen=false" /></template>
<style scoped>.rule-search{max-width:360px}.rules-scroll{margin-top:16px}.rules-scroll table{min-width:800px;table-layout:fixed}.rules-scroll th:nth-child(1){width:55px}.rules-scroll th:nth-child(2){width:auto}.rules-scroll th:nth-child(3){width:145px}.rules-scroll th:nth-child(4){width:210px}.rules-scroll th:nth-child(5){width:100px}.rule-expression p{margin-top:6px;overflow-wrap:anywhere}.rule-expression details{font-size:10px;margin-top:6px;color:var(--muted)}.rule-target{overflow-wrap:anywhere}.rule-order{display:flex;align-items:center;gap:5px}.rule-order input{width:68px;padding:5px}.rule-reason{font-size:10px}.rules-pagination{margin-top:18px}.rule-note{font-size:10px;margin-top:14px}.provider-row{display:flex;justify-content:space-between;align-items:center;padding:18px 0;border-bottom:1px solid var(--line);gap:20px}.provider-row p{font-size:11px;margin-top:5px}.rule-validation{margin-top:20px;justify-content:flex-end}.panel-header .actions{flex-wrap:wrap}@media(max-width:950px){.panel-header{align-items:flex-start;flex-direction:column}}</style>
